"""Capture browser-visible daemon data without scanning random Hub session values."""


def capture_response(bodies: list[str], response):
    bodies.append(response.text)
    # Session cookies and origin bindings are generated by the Hub, not daemon credentials.
    bodies.extend(value for name, value in response.headers.items()
                  if name.lower() not in {"set-cookie", "x-hub-session"})
    return response
